window.KY=[{"y": "r08", "label": "令和8年度", "n": 100}, {"y": "r07", "label": "令和7年度", "n": 100}, {"y": "r06", "label": "令和6年度", "n": 100}, {"y": "r05", "label": "令和5年度", "n": 100}, {"y": "r04", "label": "令和4年度", "n": 100}, {"y": "h28h", "label": "平成28年度春期", "n": 100}, {"y": "h27a", "label": "平成27年度秋期", "n": 100}, {"y": "h27h", "label": "平成27年度春期", "n": 100}];
